def evaluate_arithmetic_expression(expr: str) -> str:
    """Parse a simple arithmetic expression containing +, -, *, / and evaluate it as an integer, returning the result as a string."""
    import ast
    import operator

    ops = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.floordiv,
        ast.USub: operator.neg,
    }

    def _eval(node: ast.AST) -> int:
        if isinstance(node, ast.Num):
            return int(node.n)
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub):
            return -_eval(node.operand)
        if isinstance(node, ast.BinOp) and type(node.op) in ops:
            left = _eval(node.left)
            right = _eval(node.right)
            return ops[type(node.op)](left, right)
        raise ValueError(f"Unsupported expression: {expr}")

    tree = ast.parse(expr, mode='eval')
    result = _eval(tree.body)
    return str(result)

def solve_arithmetic_prompt(prompt: str) -> str:
    """Extract the arithmetic expression from a prompt like 'Calculate 965 / 5.' and return its integer result as a string."""
    import re
    # Find the part after 'Calculate' up to a punctuation mark or end of string
    match = re.search(r'Calculate\s+([^?.!]+)', prompt)
    if not match:
        raise ValueError('No arithmetic expression found in prompt.')
    expr = match.group(1).strip()
    return evaluate_arithmetic_expression(expr)
